/**
## /layer/featureHover

@module /layer/featureHover
*/

/**
@function featureHover

@description
The featureHover method will send an xhr request for the provided feature argument. The returned string value will be displayed in an infotip element in the feature layer mapview.

@param {object} feature
@param {layer} layer A decorated mapp layer object.
@property {object} feature.properties The feature properties object.
@property {number} feature.properties.count The number of features at the feature coordinates.
@property {string} feature.properties.id The feature id.
@property {object} layer.mapview The mapp mapview object.
@property {object} layer.style.hover The hover style object.
@property {boolean} layer.style.hover.display Whether to display hover infotips.
@property {string} layer.style.hover.field The field name to use for the hover label.
@property {function} layer.style.hover.render A function to render the hover infotip content.
*/
export default function featureHover(feature, layer) {
  // The hover method must only execute if the display flag is set.
  if (!layer.style.hover.display) return;

  // Store current highlight (feature) key.
  const featureKey = layer.mapview.interaction?.current?.key?.toString();

  if (!featureKey) return;

  // The field for hover may already exist on the feature properties, in which case it can be used directly without sending an xhr request.
  const hoverField = layer.style?.hover?.field;

  if (feature.properties?.[hoverField]) {
    // Check whether highlight feature is still current.
    if (layer.mapview.interaction?.current?.key !== featureKey) return;

    if (typeof layer.style.hover.render === 'function') {
      const content = layer.style.hover.render({
        label: feature.properties[hoverField],
        ...feature.properties,
      });
      layer.mapview.infotip(content);
    } else {
      layer.mapview.infotip(String(feature.properties[hoverField]));
    }

    return;
  }

  const table = layer.tableCurrent();

  if (!table) return;

  const queryParams = {
    coords:
      feature.properties.count > 1 &&
      ol.proj.transform(
        feature.getGeometry().getCoordinates(),
        `EPSG:${layer.mapview.srid}`,
        `EPSG:${layer.srid}`,
      ),
    field: layer.style.hover.field,
    filter: feature.properties.count > 1 && layer.filter?.current,
    geom: layer.geom,
    id: feature.properties.id,
    layer: layer.key,
    layer_template: layer.params?.layer_template,
    locale: layer.mapview.locale.key,
    qID: layer.qID,
    table,
    template: layer.style.hover.query || 'infotip',
    ...layer.queryparams,
  };

  const paramString = mapp.utils.paramString(queryParams);

  mapp.utils
    .xhr({
      url: `${layer.mapview.host}/api/query?${paramString}`,
      cache: !layer.style.hover.dynamic,
      debounce: { key: 'hover', delay: 100 },
    })
    .then((response) => {
      // Check whether there is a response to display.
      if (!response) return;

      if (typeof layer.style.hover.render === 'function') {
        const content = layer.style.hover.render(response);
        layer.mapview.infotip(content);
        return;
      }

      // Check whether the response label field has a value.
      if (response.label == '') return;

      // Check whether highlight feature is still current.
      if (layer.mapview.interaction?.current?.key !== featureKey) return;

      // Display the response label as infotip.
      layer.mapview.infotip(response.label);
    })
    .catch((_error) => {});
}
